items.source:
AuthRejection {
                    code: "AUTH_FAILED",
                    message,
                    hint: "Use PreSharedKeyCredential with the agent's paired PSK".to_string(),
                }

SessionError {
                code: "INVALID_HANDSHAKE".to_string(),
                message: "First message must be SessionInit or SessionResume".to_string(),
                hint: "Send SessionInit or SessionResume as the first message on a new stream"
                    .to_string(),
            }

SessionError {
            code: "HANDSHAKE_TIMEOUT".to_string(),
            message: "Stream closed before handshake".to_string(),
            hint: "Open a new stream and send SessionInit as the first message".to_string(),
        }

SessionError {
            code: "HANDSHAKE_ERROR".to_string(),
            message: format!("Error receiving handshake: {error}"),
            hint: "Open a new stream and send SessionInit as the first message".to_string(),
        }

SessionError {
                code: rejection.code.to_string(),
                message: rejection.message,
                hint: rejection.hint,
            }

SessionError {
                            code: "UNSUPPORTED_PROTOCOL_VERSION".to_string(),
                            message: msg,
                            hint: format!(
                                "{{\"runtime_min\": {}, \"runtime_max\": {}}}",
                                crate::auth::RUNTIME_MIN_VERSION,
                                crate::auth::RUNTIME_MAX_VERSION
                            ),
                        }

SessionError {
                        code: error_code.to_string(),
                        message,
                        hint: "Wait for session capacity to become available, then open a new stream with SessionInit"
                            .to_string(),
                    }

SessionError {
                        code: err.error_code().to_string(),
                        message: err.message().to_string(),
                        hint: err.hint().to_string(),
                    }

SessionError {
                        code: error_code.to_string(),
                        message,
                        hint: "Wait for resource capacity to become available, then open a new stream with SessionInit; this resume token has been consumed"
                            .to_string(),
                    }

SessionResumeResult {
                accepted: true,
                new_session_token: new_resume_token.clone(),
                new_server_sequence: seq,
                // Resume always runs at the highest runtime-supported version.
                // version = major * 1000 + minor; v1.1 = 1001.
                negotiated_protocol_version: crate::auth::RUNTIME_MAX_VERSION,
                active_subscriptions: prior_entry.subscriptions,
                denied_subscriptions: Vec::new(),
            }

SessionError {
                                code: "HANDSHAKE_TIMEOUT".to_string(),
                                message: "Handshake timed out (5000ms)".to_string(),
                                hint: "Send SessionInit as the first message".to_string(),
                            }

SessionError {
                                        code: code.to_string(),
                                        message,
                                        hint: format!(
                                            "Open a new stream with SessionInit or SessionResume; send increasing sequence numbers starting at 2 with gaps no larger than {DEFAULT_MAX_SEQUENCE_GAP}"
                                        ),
                                    }

RequestResult {
        seq,
        ok: true,
        ..Default::default()
    }

RequestResult {
        ids,
        lease_id: scene_id_to_bytes(lease_id),
        ttl_ms: ttl,
        ..ok(seq)
    }

RequestResult {
            ttl_ms: hold.ttl_ms,
            ..ok(seq)
        }

RequestResult {
                            lease_id: scene_id_to_bytes(lease),
                            ttl_ms: ttl,
                            ..ok(seq)
                        }

AuthRejection {
                code: "AUTH_FAILED",
                message: format!("PSK belongs to agent {agent_id:?}, not {claimed_id:?}"),
                hint: "present this agent's own PSK".into(),
            }

AuthRejection {
        code: "AUTH_FAILED",
        message: message.to_string(),
        hint: "send the agent's paired PSK as the bearer / auth_credential".to_string(),
    }
